describe('Error Boundary - UI Crash Handling', () => {
  beforeEach(() => {
    cy.visit('/app');
  });

  it('should display fallback screen when UI component crashes', () => {
    // Intercept the API call that triggers the crash
    cy.intercept('GET', '/api/data').as('getData');

    // Click the button that will trigger the error
    cy.get('[data-testid="trigger-error-button"]').click();

    // Wait for the API call
    cy.wait('@getData');

    // Verify the error boundary fallback screen is visible
    cy.get('[data-testid="error-fallback-screen"]').should('be.visible');

    // Verify the error message is displayed
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');

    // Verify the fallback component is rendered instead of the crashed component
    cy.get('[data-testid="error-fallback-component"]').should('be.visible');

    // Verify the original component is not visible
    cy.get('[data-testid="crashed-component"]').should('not.exist');

    // Verify the user can navigate away from the error screen
    cy.get('[data-testid="navigate-back-button"]').should('be.visible');
    cy.get('[data-testid="navigate-back-button"]').click();
    cy.get('[data-testid="error-fallback-screen"]').should('not.exist');
  });

  it('should handle multiple consecutive UI crashes and maintain fallback state', () => {
    // Trigger the first crash
    cy.get('[data-testid="trigger-error-button"]').click();
    cy.get('[data-testid="error-fallback-screen"]').should('be.visible');

    // Trigger a second crash
    cy.get('[data-testid="trigger-error-button"]').click();

    // Verify the fallback screen remains visible and stable
    cy.get('[data-testid="error-fallback-screen"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');

    // Verify the error count is tracked (optional, but good for robustness)
    cy.get('[data-testid="error-count"]').should('contain', '2');

    // Verify the user can still interact with the fallback screen
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').click();

    // Verify the retry button is disabled after multiple attempts (optional)
    cy.get('[data-testid="retry-button"]').should('be.disabled');
  });
});
